-- Initial voSkill schema. Run once in the application schema.
-- IDs are UUID strings generated by the application.
-- Connect as ITB2CTRF before running this script.

WHENEVER SQLERROR EXIT SQL.SQLCODE

DECLARE
    L_SESSION_USER VARCHAR2(128);
BEGIN
    L_SESSION_USER := SYS_CONTEXT('USERENV', 'SESSION_USER');
    IF UPPER(L_SESSION_USER) <> 'ITB2CTRF' THEN
        RAISE_APPLICATION_ERROR(-20010, 'Connect as ITB2CTRF before creating voSkill objects');
    END IF;
END;
/

CREATE TABLE VSK_PERSONS (
    PERSON_ID VARCHAR2(36 CHAR) NOT NULL,
    DISPLAY_NAME VARCHAR2(200 CHAR) NOT NULL,
    ACTIVE_FLAG CHAR(1 CHAR) DEFAULT 'Y' NOT NULL,
    CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT VSK_PK_PERSONS PRIMARY KEY (PERSON_ID),
    CONSTRAINT VSK_CK_PERSONS_ACTIVE CHECK (ACTIVE_FLAG IN ('Y', 'N'))
);

CREATE TABLE VSK_SKILLS (
    SKILL_ID VARCHAR2(36 CHAR) NOT NULL,
    SKILL_NAME VARCHAR2(150 CHAR) NOT NULL,
    DESCRIPTION VARCHAR2(1000 CHAR),
    CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT VSK_PK_SKILLS PRIMARY KEY (SKILL_ID),
    CONSTRAINT VSK_UQ_SKILLS_NAME UNIQUE (SKILL_NAME)
);

CREATE TABLE VSK_PERSON_COMPETENCIES (
    COMPETENCY_ID VARCHAR2(36 CHAR) NOT NULL,
    PERSON_ID VARCHAR2(36 CHAR) NOT NULL,
    SKILL_ID VARCHAR2(36 CHAR) NOT NULL,
    PROFICIENCY_LEVEL NUMBER(1) NOT NULL,
    EVIDENCE VARCHAR2(4000 CHAR) NOT NULL,
    ORIGIN_TYPE VARCHAR2(24 CHAR) DEFAULT 'MANUAL' NOT NULL,
    ACTOR_ID VARCHAR2(36 CHAR) NOT NULL,
    REVIEWED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT VSK_PK_PERSON_COMPETENCIES PRIMARY KEY (COMPETENCY_ID),
    CONSTRAINT VSK_FK_PC_PERSON FOREIGN KEY (PERSON_ID) REFERENCES VSK_PERSONS (PERSON_ID),
    CONSTRAINT VSK_FK_PC_SKILL FOREIGN KEY (SKILL_ID) REFERENCES VSK_SKILLS (SKILL_ID),
    CONSTRAINT VSK_UQ_PC_PERSON_SKILL UNIQUE (PERSON_ID, SKILL_ID),
    CONSTRAINT VSK_CK_PC_LEVEL CHECK (PROFICIENCY_LEVEL BETWEEN 1 AND 5),
    CONSTRAINT VSK_CK_PC_ORIGIN CHECK (ORIGIN_TYPE IN ('MANUAL', 'REVIEWED_SUGGESTION'))
);

CREATE TABLE VSK_PERSON_COMPETENCY_HISTORY (
    HISTORY_ID VARCHAR2(36 CHAR) NOT NULL,
    COMPETENCY_ID VARCHAR2(36 CHAR) NOT NULL,
    PREVIOUS_LEVEL NUMBER(1),
    NEW_LEVEL NUMBER(1) NOT NULL,
    PREVIOUS_EVIDENCE VARCHAR2(4000 CHAR),
    NEW_EVIDENCE VARCHAR2(4000 CHAR) NOT NULL,
    ACTOR_ID VARCHAR2(36 CHAR) NOT NULL,
    CHANGED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT VSK_PK_PCH PRIMARY KEY (HISTORY_ID),
    CONSTRAINT VSK_FK_PCH_COMPETENCY FOREIGN KEY (COMPETENCY_ID)
        REFERENCES VSK_PERSON_COMPETENCIES (COMPETENCY_ID),
    CONSTRAINT VSK_CK_PCH_PREVIOUS_LEVEL CHECK (PREVIOUS_LEVEL IS NULL OR PREVIOUS_LEVEL BETWEEN 1 AND 5),
    CONSTRAINT VSK_CK_PCH_NEW_LEVEL CHECK (NEW_LEVEL BETWEEN 1 AND 5)
);

CREATE TABLE VSK_PROJECTS (
    PROJECT_ID VARCHAR2(36 CHAR) NOT NULL,
    PROJECT_NAME VARCHAR2(200 CHAR) NOT NULL,
    HORIZON_START DATE NOT NULL,
    HORIZON_END DATE NOT NULL,
    LOAD_UNIT VARCHAR2(20 CHAR) DEFAULT 'hours' NOT NULL,
    CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT VSK_PK_PROJECTS PRIMARY KEY (PROJECT_ID),
    CONSTRAINT VSK_UQ_PROJECTS_NAME UNIQUE (PROJECT_NAME),
    CONSTRAINT VSK_CK_PROJECTS_HORIZON CHECK (
        HORIZON_START <= HORIZON_END
        AND HORIZON_START = TRUNC(HORIZON_START, 'MM')
        AND HORIZON_END = TRUNC(HORIZON_END, 'MM')
    ),
    CONSTRAINT VSK_CK_PROJECTS_LOAD_UNIT CHECK (LOAD_UNIT = 'hours')
);

CREATE TABLE VSK_PROJECT_DEMANDS (
    DEMAND_ID VARCHAR2(36 CHAR) NOT NULL,
    PROJECT_ID VARCHAR2(36 CHAR) NOT NULL,
    SKILL_ID VARCHAR2(36 CHAR) NOT NULL,
    PROFICIENCY_LEVEL NUMBER(1) NOT NULL,
    PERIOD_START DATE NOT NULL,
    LOAD_AMOUNT NUMBER(12, 2) NOT NULL,
    LOAD_UNIT VARCHAR2(20 CHAR) DEFAULT 'hours' NOT NULL,
    ACTOR_ID VARCHAR2(36 CHAR) NOT NULL,
    CREATED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATED_AT TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT VSK_PK_PROJECT_DEMANDS PRIMARY KEY (DEMAND_ID),
    CONSTRAINT VSK_FK_PD_PROJECT FOREIGN KEY (PROJECT_ID) REFERENCES VSK_PROJECTS (PROJECT_ID),
    CONSTRAINT VSK_FK_PD_SKILL FOREIGN KEY (SKILL_ID) REFERENCES VSK_SKILLS (SKILL_ID),
    CONSTRAINT VSK_CK_PD_LEVEL CHECK (PROFICIENCY_LEVEL BETWEEN 1 AND 5),
    CONSTRAINT VSK_CK_PD_PERIOD CHECK (PERIOD_START = TRUNC(PERIOD_START, 'MM')),
    CONSTRAINT VSK_CK_PD_LOAD CHECK (LOAD_AMOUNT >= 0),
    CONSTRAINT VSK_CK_PD_LOAD_UNIT CHECK (LOAD_UNIT = 'hours')
);

CREATE INDEX VSK_IX_PC_SKILL ON VSK_PERSON_COMPETENCIES (SKILL_ID);
CREATE INDEX VSK_IX_PD_PROJECT_PERIOD ON VSK_PROJECT_DEMANDS (PROJECT_ID, PERIOD_START);
CREATE INDEX VSK_IX_PD_SKILL ON VSK_PROJECT_DEMANDS (SKILL_ID);

CREATE OR REPLACE TRIGGER VSK_TRG_PROJECT_DEMAND_HORIZON
BEFORE INSERT OR UPDATE OF PROJECT_ID, PERIOD_START, LOAD_UNIT ON VSK_PROJECT_DEMANDS
FOR EACH ROW
DECLARE
    L_HORIZON_START DATE;
    L_HORIZON_END DATE;
    L_PROJECT_LOAD_UNIT VARCHAR2(20 CHAR);
BEGIN
    SELECT HORIZON_START, HORIZON_END, LOAD_UNIT
      INTO L_HORIZON_START, L_HORIZON_END, L_PROJECT_LOAD_UNIT
    FROM VSK_PROJECTS
     WHERE PROJECT_ID = :NEW.PROJECT_ID;

    IF :NEW.PERIOD_START < L_HORIZON_START OR :NEW.PERIOD_START > L_HORIZON_END THEN
        RAISE_APPLICATION_ERROR(-20001, 'Demand period is outside the project horizon');
    END IF;

    IF :NEW.LOAD_UNIT <> L_PROJECT_LOAD_UNIT THEN
        RAISE_APPLICATION_ERROR(-20002, 'Demand load unit differs from the project load unit');
    END IF;
END;
/

CREATE OR REPLACE TRIGGER VSK_TRG_PROJECT_HORIZON
BEFORE UPDATE OF HORIZON_START, HORIZON_END ON VSK_PROJECTS
FOR EACH ROW
DECLARE
    L_OUT_OF_HORIZON_COUNT NUMBER;
BEGIN
    SELECT COUNT(*)
      INTO L_OUT_OF_HORIZON_COUNT
    FROM VSK_PROJECT_DEMANDS
     WHERE PROJECT_ID = :OLD.PROJECT_ID
       AND (PERIOD_START < :NEW.HORIZON_START OR PERIOD_START > :NEW.HORIZON_END);

    IF L_OUT_OF_HORIZON_COUNT > 0 THEN
        RAISE_APPLICATION_ERROR(-20003, 'Project horizon cannot exclude existing demands');
    END IF;
END;
/